OPS = json.loads(zlib.decompress(base64.b85decode(PAYLOAD)).decode())
EXPECTED_SHA256 = "9bfaa7e1bc1e01867d623424927537b939e1075c795ab14fc18885572a7fab31"
EXPECTED_GIT_BLOB = "3ba69d07ed8e695d3b6016520ff487d41a15042a"

src = Path("index.html").read_bytes()
out = bytearray()
for op in OPS:
    if op[0] == "C":
        out.extend(src[op[1]:op[1]+op[2]])
    else:
        out.extend(base64.b64decode(op[1]))
data = bytes(out)
sha256 = hashlib.sha256(data).hexdigest()
git_blob = hashlib.sha1(f"blob {len(data)}\\0".encode() + data).hexdigest()
assert sha256 == EXPECTED_SHA256, (sha256, EXPECTED_SHA256)
assert git_blob == EXPECTED_GIT_BLOB, (git_blob, EXPECTED_GIT_BLOB)
text = data.decode("utf-8")
for banned in ["The Framework","The Story","What Makes This Different","The Big Win","The Offer","Our Ask","Jetty","The Pauli Effect","SOURCE_FILE_REF:"]:
    assert banned not in text, banned
assert "Section 7" in text
assert text.lstrip().startswith("<!DOCTYPE html>")
Path("index.html").write_bytes(data)
print("size", len(data))
print("sha256", sha256)
print("git_blob", git_blob)
